def run_2000_benchmark():
    print("=" * 105)
    print("      CUSWAY ENTERPRISE 2,000-ITEM SUPER BENCHMARK TEST (TOTAL 2,000 CASES)")
    print("=" * 105)
    
    passed = 0
    failed = 0
    failures = []
    
    processor = AICustomsClassificationProcessor()
    
    for idx, (product_name, exp_hsk, exp_heading, desc) in enumerate(TEST_2000_ITEMS, 1):
        try:
            res = processor.run_classification_pipeline(product_name=product_name, material="", function_use="", db=None)
            got_hsk = res.get("recommendedHsCode", "")
            heading = res.get("headingName", "")
            
            # Heading or 10-digit exact match validation
            is_pass = False
            if got_hsk == exp_hsk:
                is_pass = True
            elif got_hsk.split("-")[0] == exp_hsk.split("-")[0]:
                is_pass = True
            elif got_hsk[:4] == exp_heading:
                is_pass = True
                
            if is_pass:
                passed += 1
                print(f"[{idx:04d}/2000] [PASS] {product_name:<60} -> HSK: {got_hsk:<15} (Exp: {exp_hsk}) | {heading[:35]}")
            else:
                failed += 1
                failures.append((product_name, got_hsk, exp_hsk, desc))
                print(f"[{idx:04d}/2000] [FAIL] {product_name:<60} -> Got: {got_hsk:<15} (Exp: {exp_hsk}) | {heading[:35]}")
        except Exception as e:
            failed += 1
            failures.append((product_name, str(e), exp_hsk, desc))
            print(f"[{idx:04d}/2000] [ERROR] {product_name:<60} -> Error: {e}")

    print("=" * 105)
    print("                             FINAL 2,000 BENCHMARK SCORE SUMMARY")
    print("=" * 105)
    total = len(TEST_2000_ITEMS)
    pass_rate = (passed / total) * 100.0
    err_rate = (failed / total) * 100.0
    print(f"TOTAL SCORE     : {passed}/{total} ({pass_rate:.1f}%)")
    print(f"ERROR RATE      : {err_rate:.1f}% (Target: 0.0%)")
    print("=" * 105)
    
    if failures:
        print(f"\n[FAILURES TO RESOLVE] ({len(failures)} items):")
        for p, got, exp, desc in failures[:30]:
            print(f"  - {p} | Got: {got} | Expected: {exp}")
        sys.exit(1)
    else:
        print("\n>>> ALL 2,000 BRAND NEW TEST CASES PASSED WITH 0.0% ERROR RATE! <<<\n")
        sys.exit(0)

if __name__ == "__main__":
    run_2000_benchmark()
